$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$repo = (Resolve-Path (Join-Path $root '../..')).Path
$output = Join-Path $repo 'Kotowari.Benchmarks/Results/experiments/2026-10-19-json-value-order.json'
$baselineCommit = 'e9be3daba67610437bd3d1b6e19004279f95a775'
$inputHash = 'DC87DD0FB85CB6F875AC336B70FEFC1E32BB1F284C8F6E011E0CB0256F9A354D'
$coreHash = '711A6D91E2BF0132ABB50DEC81A5B80555CDDF2BD0F4D3B8F5C849AC2F676BA8'
function Hash($p) { (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash }
function Rel($p) { [IO.Path]::GetRelativePath($repo,$p).Replace('\','/') }
function Json($p) { Get-Content -LiteralPath $p -Raw | ConvertFrom-Json -DateKind String }

$parentPath = Join-Path $root 'parent-validation.json'
$parent = Json $parentPath
$manifestPath = Join-Path $root 'dll-manifest.json'
$manifest = Json $manifestPath
foreach ($v in 'baseline','candidate') {
    foreach ($dll in $manifest.$v) { if ((Hash (Join-Path $root "$v/host/$($dll.Name)")) -ne $dll.SHA256) { throw "Frozen host mismatch: $v/$($dll.Name)" } }
}
$baseValidation = Json (Join-Path $root 'baseline/validation.json')
$candidateValidation = Json (Join-Path $root 'candidate/validation.json')
foreach ($v in @($baseValidation,$candidateValidation)) { if ($v.ExitCode -ne 0 -or -not $v.FullInputConsumed -or $v.ExpectedNodeCount -ne 100001 -or -not $v.SystemTextJsonTreeEquivalent -or $v.InputSHA256 -ne $inputHash) { throw "Validation failure: $($v.Variant)" } }
$summaryPath = Join-Path $root 'exploration-summary.json'
$summary = Json $summaryPath
if ($summary.Experiment -ne '2026-10-19-json-value-order' -or $summary.PairCount -ne 8 -or $summary.DegreesOfFreedom -ne 7) { throw 'Exploration identity/design mismatch.' }
$runs = @()
foreach ($i in 1..8) {
    foreach ($variant in 'baseline','candidate') {
        $name = '{0:d2}-{1}' -f $i,$variant
        $dir = Join-Path $root "runs/exploration/$name"
        $sp = Join-Path $dir 'run-summary.json'; $s = Json $sp
        if ($s.ExitCode -ne 0 -or $s.ActualCount -ne 8 -or $s.ResultCount -ne 8 -or $s.WarmupCount -ne 16 -or $s.InputSHA256 -ne $inputHash -or $s.LibraryDLLSHA256 -ne $coreHash -or $s.Affinity -ne 4 -or $s.TieredPGO -ne 1) { throw "Run invalid: $name" }
        $hl = Join-Path $dir $s.HostLog; $el = Join-Path $dir $s.Stderr
        if ((Get-Item $el).Length -ne 0 -or [IO.File]::ReadAllText($hl) -notmatch '(?m)^// AfterAll\s*$') { throw "Run logs invalid: $name" }
        $runs += [ordered]@{Name=$name;SummaryPath=Rel $sp;SummarySHA256=Hash $sp;Summary=$s;HostLogPath=Rel $hl;HostLogSHA256=Hash $hl;StderrPath=Rel $el;StderrSHA256=Hash $el}
    }
}
$envPath = Join-Path $root 'environment.json'; $envRecords = @(Json $envPath)
if ($envRecords.Count -ne 8) { throw 'Expected 8 pre-pair environment records.' }
foreach ($e in $envRecords) { if ($e.ACLineStatus -ne 1 -or $e.BatterySaver -ne 0 -or $e.Stage -notmatch '^Before-exploration-[1-8]$') { throw "Bad environment: $($e.Stage)" } }
$sourcePath = Join-Path $repo 'JsonParser/JSON.cs'
$testPath = Join-Path $repo 'JsonParserのテスト/JSONのテスト.cs'
$patchText = (& git -C $repo diff --binary $baselineCommit -- JsonParser/JSON.cs 'JsonParserのテスト/JSONのテスト.cs' | Out-String)
if ($LASTEXITCODE -ne 0 -or $patchText -notmatch 'literal' -or $patchText -notmatch 'array') { throw 'Candidate source/test diff not found.' }
$jit = [ordered]@{}
foreach ($variant in 'baseline','candidate') {
    $d = Join-Path $root "diagnostics/jit/$variant/capture-01"
    $cp = Join-Path $d 'capture.json'; $asm = Join-Path $d 'jit.asm'; $j = Json $cp
    if ($j.ExitCode -ne 0 -or -not $j.DiagnosticOnly) { throw "JIT capture invalid: $variant" }
    $jit[$variant]=[ordered]@{CapturePath=Rel $cp;CaptureSHA256=Hash $cp;AssemblyPath=Rel $asm;AssemblySHA256=Hash $asm;Capture=$j;DiagnosticOnly=$true}
}
$allocMean = [ordered]@{}
foreach ($v in 'baseline','candidate') { $vals=@($runs | Where-Object {$_.Summary.Variant -eq $v} | ForEach-Object {$_.Summary.AllocatedBytesPerOperation}); $allocMean[$v]=($vals | Measure-Object -Average).Average }
$scripts=@(Get-ChildItem (Join-Path $root 'scripts') -File | Sort-Object Name | ForEach-Object {[ordered]@{Path=Rel $_.FullName;SHA256=Hash $_.FullName;Body=[IO.File]::ReadAllText($_.FullName)}})
$candidateParser=($manifest.candidate | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
$baselineParser=($manifest.baseline | Where-Object Name -eq 'Marimo.Parser.dll').SHA256
$evidence=[ordered]@{
 Experiment='2026-10-19-json-value-order'
 Decision=[ordered]@{Outcome='Not adopted for speed';Rule='Exploration upper CI < 1 required before separate confirmation; confirmation upper CI < 1 required for adoption.';PairedGeometricMeanRatio=$summary.PairedGeometricMeanRatio;Confidence95=$summary.Confidence95;PairCount=8;DegreesOfFreedom=7;TCritical95Df7=2.364624251;Interpretation='The full interval is above 1, supporting a slowdown under this workload; no independent confirmation was run.'}
 Change=[ordered]@{BaselineCommit=$baselineCommit;SourcePath=Rel $sourcePath;SourceSHA256=Hash $sourcePath;SourceDiff=$patchText;TestPath=Rel $testPath;TestSHA256=Hash $testPath;TestFullSource=[IO.File]::ReadAllText($testPath);ParentValidationPath=Rel $parentPath;ParentValidationSHA256=Hash $parentPath;ParentValidation=$parent;Behavior='JValue alternative order only: array, object, literal -> literal, array, object; parser/getter structures and types unchanged.'}
 Input=[ordered]@{Path='Kotowari.Benchmarks/Data/test.json';Bytes=4172062;SHA256=$inputHash;ExpectedNodeCount=100001}
 FrozenHosts=[ordered]@{ManifestPath=Rel $manifestPath;ManifestSHA256=Hash $manifestPath;Manifest=$manifest;OnlyParserDiff=$true;BaselineParserSHA256=$baselineParser;CandidateParserSHA256=$candidateParser;FixedCoreSHA256=$coreHash;BaselineValidation=$baseValidation;CandidateValidation=$candidateValidation}
 Workload=[ordered]@{Method='Marimo.Kotowari.Benchmarks.JsonStreamBenchmarks.StringInput';Scope='MemoryStream creation/copy, UTF-8 decoding, complete parse and JSON tree generation; physical disk excluded.';TieredPGO=1;Affinity=4;Warmup=16;Actual=8;Result=8;Invocation=4;Unroll=1;OutlierMode='DontRemove';FreshProcessPerObservation=$true}
